    def test_extras(self):
        rows=[({'port':8}, {}, True),({'port':8},{'additionalProperties':True},True),({'port':8},{'additionalProperties':False},False),({}, {'additionalProperties':False},True),({'port':8},{'properties':{'port':{}},'additionalProperties':False},True),({'prefix_S_x':3},{'patternProperties':{'S_':{}},'additionalProperties':False},True),({'S_x':3,'extra':2},{'patternProperties':{'^S_':{}},'additionalProperties':False},False),({'xS':3},{'patternProperties':{'^S':{}},'additionalProperties':False},False)]
        for value,schema,want in rows:
            self.assertEqual(app.allows_extras(value,schema),want)


if __name__ == "__main__":
