class CombinedCoverage(unittest.TestCase):
    def test_union_and_allow(self):
        schema = {'properties': {'port': {}}, 'patternProperties': {'^S_': {}, 'dock$': {}}, 'additionalProperties': False}
        self.assertTrue(app.allows_extras({'port': 0, 'S_zone': None, 'drydock': False}, schema))
        self.assertFalse(app.allows_extras({'port': 0, 'S_zone': 1, 'other': 2}, schema))
        schema['additionalProperties'] = True
        self.assertTrue(app.allows_extras({'other': 2}, schema))
        self.assertTrue(app.allows_extras({'any': 2}, {'patternProperties': {'': {}}, 'additionalProperties': False}))

