import re

def allows_extras(value, schema):
    if schema.get('additionalProperties', True):
        return True
    names = schema.get('properties', {})
    patterns = schema.get('patternProperties', {})
    return all(key in names or any(re.search(p, key) for p in patterns) for key in value)
